import { Component, h, Prop } from '@stencil/core';

@Component({
  tag: 'std-table-th',
  styleUrl: 'std-table-th.css',
  shadow: true
})
export class StdTableThComponent {
  @Prop() titleTh: string;
  @Prop() icon: boolean;
  @Prop() href: string;
  @Prop() positionClasses: string;

  componentDidLoad() {
    this.positionClasses;
  }

  render() {
    // se agrego w-full para que el webcomponent tome el 100% del tamaño dado por el padre
    const contentClasses = ['flex items-center gap-1 w-full', this.positionClasses].join(' ').trim().replace(/\s+/g, ' ');

    return (
      <th scope="col" class="px-6 py-3">
        <div class={contentClasses}>
          <span class="font-bold text-dark text-base leading-4"> {this.titleTh}</span>
          {this.icon && (
            <a href={this.href} class="cursor-pointer">
              <i class="icon-arrow-down text-altenative text-base leading-none" />
            </a>
          )}
        </div>
      </th>
    );
  }
}
