import { Component, Event, EventEmitter, Prop, State, h } from '@stencil/core';

@Component({
  tag: 'std-download-dropdown',
  styleUrl: 'std-download-dropdown.css',
  shadow: true
})
export class StdDownloadDropdown {
  @Prop() optionsList: { label: string; value: string; disabled: boolean }[] = [];
  @Prop() label: string = '';
  @Prop() size: string = '';
  @Prop() isLoadingButton: boolean = false;

  @State() isOpen: boolean = false;
  @State() setValueRadioButton: string = '';
  @State() canDisableDownloadButton: boolean = true;
  @State() isModalOpen: boolean = false;

  @Event() downloadSelected: EventEmitter<string>;

  onClickOpenModal() {
    if (this.isOpen) {
      this.isOpen = !this.isOpen;
      return;
    }

    this.isModalOpen = !this.isModalOpen;
    if (!this.isModalOpen) {
      this.setValueRadioButton = '';
      this.canDisableDownloadButton = true;
    }
  }

  onClickShowOptions() {
    this.isOpen = !this.isOpen;
    if (!this.isOpen) {
      this.setValueRadioButton = '';
      this.canDisableDownloadButton = true;
    }
  }

  onclickDownloadFile(): void {
    this.downloadSelected.emit(this.setValueRadioButton);
  }

  onClickRadioButton(event: any, disabled: boolean): void {
    if (disabled) return;
    this.setValueRadioButton = event;
    this.canDisableDownloadButton = false;
  }

  render() {
    return (
      <div class="flex flex-col gap-1">
        <div
          class={{
            'relative css-select css-collapse js-collapse w-full bg-white rounded-[32px] shadow-[0_4px_10px_#A3A3A366]': true,
            'border-2 border-[#127277]': this.isOpen,
            'border border-white': !this.isOpen
          }}>
          <button
            onClick={() => this.onClickShowOptions()}
            type="button"
            class="css-collapse-header js-collapse-header inline-flex w-full items-center justify-between px-[11px] py-[4px] text-base text-alternative rounded-lg font-bold gap-1 hidden lg:inline-flex">
            <i class="text-alternative font-bold text-lg icon-download"></i>
            <span class="text-ellipsis whitespace-nowrap overflow-hidden text-sm">{this.label}</span>
            <i class="icon-chevron-down text-alternative text-2xl leading-none"></i>
          </button>
          <button
            onClick={() => this.onClickOpenModal()}
            type="button"
            class="inline-flex w-full items-center justify-between px-[11px] py-[4px] text-base text-alternative rounded-lg font-bold inline-flex lg:hidden gap-1"
            data-modal="modal-options-download">
            <i class="text-alternative font-bold text-lg icon-download text-sm"></i>
            <span class="text-ellipsis whitespace-nowrap overflow-hidden">{this.label}</span>
            <i class="icon-chevron-down text-alternative text-2xl leading-none"></i>
          </button>
          <div>
            {this.isOpen && (
              <div
                style={{ top: '45px' }}
                class="css-collapse-body js-collapse-body flex-col right-[-1px] bg-white absolute z-10 shadow-modal rounded-lg overflow-y-auto max-h-[300px]">
                <ul class="flex flex-col justify-end gap-4 lg:gap-2 lg:p-2 h-full">
                  {this.optionsList.map(option => (
                    <li
                      class={{
                        'border rounded flex justify-between p-4 border-2 transition-all': true,
                        'border-[#127277] bg-alternative-light ': this.setValueRadioButton === option.value,
                        'border-border-disabled': this.setValueRadioButton !== option.value,
                        'bg-disabledselect border rounded-lg border-border-disabled': option.disabled === true,
                        'w-[232px]': this.size === 'm'
                      }}>
                      <label class="flex gap-2 justify-between w-full itemRadioCheck">
                        <span
                          class={{
                            'text-left': true,
                            'w-[252px]': this.size === 'l',
                            'w-[110px]': this.size === 's',
                            'text-dark/[0.23]': option.disabled === true
                          }}>
                          {option.label}
                        </span>
                        <input
                          class={{
                            'w-6 h-6 rounded-full outline-0 checked:bg-[length:13px] checked:border-[2px] text-alternative border-border-default checked:text-white checked:bg-radio-checked checked:border-alternative checked:hover:border-alternative false':
                              true,
                            'text-dark/[0.06] bg-dark/[0.06]': option.disabled === true
                          }}
                          type="radio"
                          name="typeFile"
                          disabled={option.disabled}
                          onClick={() => this.onClickRadioButton(option.value, option.disabled)}
                        />
                      </label>
                    </li>
                  ))}
                  <std-button
                    size="s"
                    class="my-2 !w-full"
                    icon-position="left"
                    label="Descargar"
                    disabled={this.canDisableDownloadButton}
                    loading={this.isLoadingButton}
                    onClick={() => this.onclickDownloadFile()}
                    type="primary"
                  />
                </ul>
              </div>
            )}
          </div>
          <std-modal size="m" show={this.isModalOpen} onIconClick={() => this.onClickOpenModal()}>
            <div class="flex flex-col gap-4 w-full text-center">
              <div class="flex flex-col gap-6">
                <h2 class="font-bold text-2xl">Descargar</h2>
                <ul class="flex flex-col  justify-end gap-4 lg:gap-2 lg:p-2 h-full">
                  {this.optionsList.map(option => (
                    <li
                      class={{
                        'border rounded flex justify-between p-4 border-2 transition-all': true,
                        'border-[#127277] bg-alternative-light ': this.setValueRadioButton === option.value,
                        'border-border-disabled': this.setValueRadioButton !== option.value,
                        'bg-disabledselect border rounded-lg border-border-disabled': option.disabled === true
                      }}>
                      <label class="flex gap-2 justify-between w-full">
                        <span
                          class={{
                            'w-[110px] text-left': true,
                            'text-dark/[0.23]': option.disabled === true
                          }}>
                          {option.label}
                        </span>
                        <input
                          class={{
                            'w-6 h-6 rounded-full outline-0 checked:bg-[length:13px] checked:border-[2px] text-alternative border-border-default checked:text-white checked:bg-radio-checked checked:border-alternative checked:hover:border-alternative false':
                              true,
                            'text-dark/[0.06] bg-dark/[0.06]': option.disabled === true
                          }}
                          type="radio"
                          name="typeFile"
                          disabled={option.disabled}
                          onClick={() => this.onClickRadioButton(option.value, option.disabled)}
                        />
                      </label>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
            <div slot="footer" class="w-full">
              <std-button
                size="s"
                class="my-2 !w-full"
                icon-position="left"
                label="Descargar"
                disabled={this.canDisableDownloadButton}
                loading={this.isLoadingButton}
                onClick={() => this.onclickDownloadFile()}
                type="primary"
              />
            </div>
          </std-modal>
        </div>
      </div>
    );
  }
}
