import { Component, Event, EventEmitter, h, Prop } from '@stencil/core';

@Component({
  tag: 'std-password-generator',
  styleUrl: 'std-password-generator.css',
  shadow: true
})
export class StdTab {
  @Prop() titleBox: string = '';
  @Prop() label: string = '';
  @Prop() description: string = '';
  @Prop() status: string = '';
  @Prop() typeButton: string = '';
  @Prop() labelButton: string = '';
  @Prop() disabled: boolean = false;

  @Event() clickButtonEvent: EventEmitter;

  render() {
    const generatorClasses = ['flex flex-col lg:flex-row lg:justify-between gap-4', this.status].join(' ').trim().replace(/\s+/g, ' ');

    const onButtonClick = (e: MouseEvent) => {
      e.preventDefault();
      this.clickButtonEvent.emit(e);
    }

    return (
      <div class="rounded-lg flex flex-col gap-5 p-6 border border-alternative-medium lg:flex-1">
        <div class="flex items-center justify-between flex-wrap gap-2">
          <h3 class="relative after:content-[''] after:absolute after:-bottom-2 after:left-0 after:w-6 after:h-[2px] after:bg-primary text-dark text-lg font-bold flex items-center gap-2">
            {this.titleBox}
          </h3>
        </div>
        <div>
          <div class={generatorClasses}>
            <div class="flex gap-2">
              <std-support-icons type={this.status} classes="password-generator"/>
              <div class="flex flex-col lg:pt-2 gap-1">
                <p class="text-dark text-2xl font-bold">{this.label}</p>
                <p class="text-dark text-base">{this.description}</p>
              </div>
            </div>
            <div><std-button onClick={(e) => onButtonClick(e)} classes="w-full lg:w-auto" type={this.typeButton} label={this.labelButton} disabled={this.disabled} ></std-button> </div>
          </div>
        </div>
      </div>
    );
  }
}
