import { Component, Event, EventEmitter, Prop, h } from '@stencil/core';

@Component({
  tag: 'std-banner',
  styleUrl: 'std-banner.css',
  shadow: true
})
export class StdBannerComponent {
  @Prop() label: string;
  @Prop() back: boolean;
  @Prop() href: string;

  @Event() clickBack: EventEmitter;

  onBackClick(event: Event) {
    if (this.href) {
      return (window as any).navigateTo(this.href);
    }
    event.preventDefault();
    this.clickBack.emit(event);
  }

  render() {
    return (
      <div class="bg-alternative-light flex flex-col w-full py-4 pl-4 pr-12 lg:py-6 lg:pl-7 lg:pr-20 rounded-2xl relative overflow-hidden gap-4 lg:gap-6">
        <slot></slot>
        <div class="flex items-center justify-between w-full">
          <h2 class="text-lg lg:text-3xl font-bold text-dark flex items-center gap-2 cursor-default">
            {this.back && (
              <a onClick={e => this.onBackClick(e)}>
                <i class="icon-arrow-left-2px text-alternative text-xl leading-none cursor-pointer flex" />
              </a>
            )}
            {this.label}
          </h2>
          <std-image
            classes="block w-20 h-20 lg:w-40 lg:h-40 absolute bottom-0 lg:bottom-[-47px] right-4 lg:right-6"
            imageClasses="aspect-[3/1] lg:aspect-auto"
            src="assets/images/svg/buildings.svg"
            srcDesktop="assets/images/svg/buildings.svg"
            alt="Alt"
          />
        </div>
      </div>
    );
  }
}
