import { Component, Method, Prop, State, h, Event, EventEmitter, Listen } from '@stencil/core';
import localeEs from './air-datepicker/locale/es';
import AirDatepicker from './air-datepicker/air-datepicker';
import { daysBetween } from '../../utils/utils';

@Component({
  tag: 'std-calendar',
  styleUrl: 'std-calendar.css',
  shadow: true
})
export class StdCalendar {
  @Prop() minDate: Date | string | number = null;
  @Prop() maxDate: Date | string | number = null;
  @Prop() maxRangeDays: number;
  @Prop() buttonLabelOk: string = 'Aplicar';
  @Prop() buttonLabelClear: string = 'Limpiar';
  @Prop() range: boolean = true;

  @State() showCalendar: boolean = false;
  @State() startDate: Date | null = null;
  @State() endDate: Date | null = null;
  @State() selectedDates: string = '';

  // for input
  @Prop() disabledAsReadonly = false;
  @Prop() disabled: boolean;
  @Prop() readonly: boolean;
  @Prop() helperText: string;
  @Prop() status = 'default';
  @Prop() placeholder: string = 'Seleccione un rango';
  @Prop() label: string = 'Rango de fechas';
  @Prop() isPositionAbsolute: boolean = true;
  @Prop() classesContainer: string = '';

  airDatepickerInstance: any = null;
  calendarMenu: HTMLDivElement;
  inputElement: HTMLStdInputElement;

  @Event() changeCalendar: EventEmitter;
  @Event({
    bubbles: false
  })
  blurEvent: EventEmitter;
  @Event() invalidRange: EventEmitter;

  componentDidLoad() {
    if (this.airDatepickerInstance) return;
    this.initCalendar();
  }

  @Method()
  async reset() {
    this.setCalendarInstance([]);
    this.clearStateVariables();
    this.onChangeCalendar([]);
    this.airDatepickerInstance.setViewDate(new Date());
  }

  @Method()
  async onSelected() {
    const dates = !this.range ? this.formatDate(this.startDate) : [this.formatDate(this.startDate), this.formatDate(this.endDate)];
    this.onChangeCalendar(dates);
  }

  @Method()
  async setRange(startDate: string, endDate: string) {
    if (!startDate || !endDate) {
      return;
    }
    this.setCalendarInstance([this.startDate, this.endDate]);
    this.setStateVariables(startDate, endDate);
  }

  @Method()
  async setDate(date: string) {
    if (!date) return;
    this.startDate = this.parseStringToDate(date);
    this.setCalendarInstance([this.startDate]);
    this.selectedDates = this.formatDate(this.startDate, true);
  }

  private setCalendarInstance(dates: Date[]) {
    this.airDatepickerInstance.clear();
    this.airDatepickerInstance.update({
      selectedDates: [...dates]
    });
  }

  //emitters
  private onChangeCalendar(value: string | string[]) {
    this.changeCalendar.emit(value);
  }
  private onSelectBlur() {
    this.blurEvent.emit();
  }

  // state variables
  private clearStateVariables() {
    this.startDate = null;
    this.endDate = null;
    this.selectedDates = '';
  }

  private setStateVariables(startDate: string, endDate: string) {
    this.startDate = this.parseStringToDate(startDate);
    this.endDate = this.parseStringToDate(endDate);
    this.selectedDates = `${this.formatDate(this.startDate, true)} - ${this.formatDate(this.endDate, true)}`;
  }

  // utils
  private formatDate(date: Date, withSlash?: boolean): string {
    if (!date) return null;

    const day = String(date.getDate()).padStart(2, '0');
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const year = date.getFullYear();
    return withSlash ? `${day}/${month}/${year}` : `${year}-${month}-${day}`;
  }

  private parseStringToDate(stringDate: string, separator: '/' | '-' = '-'): Date {
    const [year, month, day] = stringDate.split(separator);
    return new Date(+year, +month - 1, +day); // month is 0-indexed in JavaScript Date
  }

  private toggleCollapse() {
    if (this.readonly || this.disabled) return;
    this.showCalendar = !this.showCalendar;
    if (!this.showCalendar) {
      this.airDatepickerInstance.hide();
    }
  }

  async initCalendar() {
    this.airDatepickerInstance = new AirDatepicker(this.calendarMenu, {
      buttons: [
        {
          content: this.buttonLabelClear,
          onClick: () => this.reset()
        },
        {
          content: this.buttonLabelOk,
          className: 'air-datepicker-button--apply',
          onClick: picker => {
            picker.hide();
            this.showCalendar = false;
          }
        }
      ],
      classes: 'css-calendar',
      locale: localeEs,
      multipleDatesSeparator: ' - ',
      position: 'bottom right',
      dateFormat: 'dd/MM/yyyy',
      range: this.range,
      dynamicRange: false,
      minDate: this.minDate ?? undefined,
      maxDate: this.maxDate ?? undefined,
      disableNavWhenOutOfRange: true,
      onHide: isFinished => {
        if (!this.range) return;
        this.endDate ? this.onSelected() : !isFinished ? this.reset() : null;
      },
      onSelect: opts => {
        const { date, formattedDate } = opts;
        // if (!date) return;
        const newFormattedDate = Array.isArray(formattedDate) ? formattedDate : [formattedDate];
        this.selectedDates = newFormattedDate.join(' - ');
        this.startDate = this.range ? date[0] : (date as Date);
        this.endDate = this.range ? (Array.of(date).length > 0 ? date[1] : null) : null;
        if (!this.range) {
          this.onSelected();
        }
        // if (formattedDate.length === 0) return this.reset();
      },
      onBeforeSelect: ({ date, datepicker }) => {
        if (!this.maxRangeDays) {
          return true;
        }

        const isRange = datepicker.selectedDates.length == 1;
        const rangeDays = this.startDate && daysBetween(date, this.startDate);
        const isValidRange = rangeDays < this.maxRangeDays;
        isRange && !isValidRange && this.invalidRange.emit();

        return !isRange || isValidRange;
      }
    });
  }

  @Listen('click', { target: 'document' })
  checkForClickOutside(ev: PointerEvent): void {
    const path = ev.composedPath();
    if (this.showCalendar && !path.includes(this.inputElement) && !path.includes(this.calendarMenu)) {
      this.onSelectBlur();
      this.showCalendar = false;
      this.airDatepickerInstance.hide();
      return;
    }
  }

  render() {
    const containerClasses = ['mt-[10px]  z-50 w-full', this.isPositionAbsolute ? 'absolute' : 'relative', this.classesContainer].join(' ').trim().replace(/\s+/g, ' ');

    return (
      <div class="flex flex-col gap-1 relative">
        <div class="relative">
          <std-input
            onKeyDown={e => e.preventDefault()}
            ref={el => (this.inputElement = el)}
            placeholder={this.placeholder}
            label={this.label}
            onClick={() => this.toggleCollapse()}
            value={this.selectedDates}
            disabled={this.disabled}
            readonly={this.readonly}
            helperText={this.helperText}
            status={this.status}
            disabledAsReadonly={this.disabledAsReadonly}
            icon="calendar"
            iconClass="cursor-pointer"
          />
          <div ref={el => (this.calendarMenu = el)} id="calendarId" class={this.showCalendar ? containerClasses : 'hidden'} />
        </div>
      </div>
    );
  }
}
