import { Component, EventEmitter, h, Prop, Event } from '@stencil/core';

@Component({
  tag: 'std-text-area',
  styleUrl: 'std-text-area.css',
  shadow: true
})
export class StdTextAreaComponent {
  @Prop() label: string;
  @Prop() name: string;
  @Prop() htmlId: string;
  @Prop() icon: string;
  @Prop() placeholder: string;
  @Prop() helperText: string;
  @Prop() status = 'default';
  @Prop() disabled: boolean;
  @Prop() readonly: boolean;
  @Prop() classes: string;
  @Prop() max: any = 0;
  @Prop() counter: boolean;
  @Prop() rows: number = 2;
  @Prop({ mutable: true }) value: string;

  @Event() changeEvent: EventEmitter;
  @Event() nativeChangeEvent: EventEmitter;

  onInputChanged(event: InputEvent): void {
    const target = event.target as HTMLInputElement;
    this.value = target.value;
    this.changeEvent.emit(this.value);
  }

  onInputNativeChange(event: Event): void {
    this.nativeChangeEvent.emit(event);
  }

  render() {
    const statusClasses = {
      default: 'border-border-default hover:border-dark focus:border-alternative focus:ring-alternative',
      success: 'border-border-default hover:border-dark focus:border-alternative focus:ring-alternative',
      error: 'border-error focus:border-error focus:ring-error'
    }[this.status];

    const textareaClasses = [
      'w-full rounded-lg p-3 placeholder:text-soft',
      this.readonly || this.disabled ? '' : statusClasses,
      this.readonly && 'bg-dark/[0.06] border-transparent focus:border-transparent focus:ring-transparent',
      this.disabled && 'bg-dark/[0.06] text-dark/[0.23] border-transparent',
      this.icon && 'pr-12',
      this.classes
    ]
      .join(' ')
      .trim()
      .replace(/\s+/g, ' ');

    const labelClasses = this.disabled && 'text-dark/[0.23]';

    const iconClasses = [
      'absolute top-3 right-3 text-2xl leading-none',
      !this.readonly && !this.disabled ? 'text-alternative' : '',
      this.readonly && 'text-soft',
      this.disabled && 'text-dark/[0.23]',
      `icon-${this.icon}`
    ]
      .join(' ')
      .trim()
      .replace(/\s+/g, ' ');

    return (
      <div class="flex flex-col gap-1 relative">
        {this.label && (
          <label htmlFor={this.htmlId} class={labelClasses}>
            {this.label}
            {this.counter && (
              <span class="text-dark text-sm absolute right-1">{this.value?.length || 0}/{this.max}</span>
            )}
          </label>
        )}
        <div class="relative">
          <textarea
            value={this.value}
            onInput={e => this.onInputChanged(e)}
            onChange={e => this.onInputNativeChange(e)}
            maxlength={this.max}
            rows={this.rows}
            class={textareaClasses}
            id={this.htmlId}
            name={this.name}
            placeholder={this.placeholder}
            disabled={this.disabled}
            readonly={this.readonly}>
            {this.value}
          </textarea>
          {this.icon && <i class={iconClasses} />}
        </div>
        {this.helperText && <std-helpertext label={this.helperText} status={this.status} disabled={this.disabled} />}
      </div>
    );
  }
}
