import { Component, Event, EventEmitter, h, Prop, State, Watch } from '@stencil/core';

interface TabItem {
  label: string;
  key: number;
  active: boolean;
  disabled?: boolean;
}

@Component({
  tag: 'std-tab',
  styleUrl: 'std-tab.css',
  shadow: true
})
export class StdTab {
  @Prop() type: string = '';
  @Prop() bgStyle = '';
  @Prop() activeStyle = '';
  @Prop() items: any; // [{ label: 'Tab 1', key: 1 }, { label: 'Tab 2', key: 2}
  @Prop({ mutable: true }) tabKey: string;

  @State() internalItems: TabItem[] = [];
  @Event() itemSelected: EventEmitter<{ selectedKey: string }>;

  componentWillLoad() {
    this.parseOptions();
  }

  @Watch('items')
  parseOptions() {
    let finalItems = [];
    if (!this.items) return;
    if (typeof this.items === 'string') {
      finalItems = JSON.parse(this.items);
    } else {
      finalItems = this.items;
    }
    this.internalItems = finalItems as TabItem[];
  }

  render() {
    const typeClassesTab = {
      primary: 'css-tab',
      secondary: 'css-tab--simple'
    }[this.type];

    const tabClasses = [typeClassesTab].join(' ').trim().replace(/\s+/g, ' ');

    // Header //
    const typeClasses = {
      primary: `inline-flex items-center gap-4 p-1 rounded-xl ${this.bgStyle || 'bg-alternative-light'}`,
      secondary: 'flex items-center gap-4 border-b border-alternative-medium'
    }[this.type];

    const tabHeaderClasses = [typeClasses].join(' ').trim().replace(/\s+/g, ' ');

    const buttonTypeClasses = {
      primary: ' px-8',
      secondary: 'px-2'
    }[this.type];

    const buttonClasses = ['css-tab-button  h-auto py-2 lg:py-3 text-base text-dark', buttonTypeClasses].join(' ').trim().replace(/\s+/g, ' ');

    const onChangeActive = (key: string) => {
      if (this.tabKey === key) return
      this.tabKey = key;
      this.itemSelected.emit({ selectedKey: key });
    }

    return (
      <div class={tabClasses}>
        {/* Header */}
        <ul class={tabHeaderClasses}>
          {this.internalItems.map(item => (
            <li>
              <button onClick={() => onChangeActive(String(item.key))}
                class={
                  `${buttonClasses} ${String(this.tabKey) === String(item.key) 
                  ? `is-active ${this.activeStyle || ''}` 
                  : ''}`
                }
                disabled={item.disabled}>
                {item.label}
              </button>
            </li>
          ))}
        </ul>
        {/* Fin Header */}
        <div class="pt-4">
          <slot />
        </div>
      </div>
    );
  }
}
