import { Component, h, Prop} from '@stencil/core';

@Component({
  tag: 'std-tab-item',
  styleUrl: 'std-tab-item.css',
  shadow: true
})
export class StdTabItem {
  @Prop({mutable: true}) active: boolean;

  render() {
    const tabItemClasses = [
      'css-tab-pane',
      'hidden',
      this.active && 'is-active',
    ]
      .join(' ')
      .trim()
      .replace(/\s+/g, ' ')
    return (
      <div class={tabItemClasses}>
        <slot />
      </div>
    );
  }
}
