import { Component, Event, h, Prop, State, Watch, EventEmitter } from '@stencil/core';

interface IitemBread {
  label: string;
  actionKey?: string;
}
@Component({
  tag: 'std-breadcrumbs',
  styleUrl: 'std-breadcrumbs.css',
  shadow: true
})
export class StdBreadcrumbComponent {
  @Prop() items: any;
  @State() internalItems: IitemBread[] = [];

  @Event() itemSelected: EventEmitter<{ actionKey: string }>;

  handleClick(item: IitemBread) {
    if (!item?.actionKey) return;
    this.itemSelected.emit({ actionKey: item.actionKey });
  }

  componentWillLoad() {
    this.parseOptions();
  }

  @Watch('items')
  parseOptions() {
    let finalItems = this.items;
    if (!this.items) return;
    if (typeof this.items === 'string') {
      finalItems = JSON.parse(this.items);
    }
    if (finalItems.some(e => typeof e === 'string')) {
      finalItems = finalItems.map(value => {
        return {
          label: value
        };
      });
    }
    this.internalItems = finalItems as IitemBread[];
  }

  render() {
    const baseClasses = `text-sm text-alternative first:!text-alternative font-bold after:content-['] after:border-solid after:border-r-[3px] after:border-b-[3px] after:-rotate-45 after:p-[3px] after:inline-block last:after:hidden last:text-dark`;

    return (
      <div>
        <ol class="flex items-center flex-wrap gap-2">
          {this.internalItems.map(item => (
            <li onClick={() => this.handleClick(item)} class={`${baseClasses} ${item.actionKey ? 'cursor-pointer' : 'cursor-default'}`}>
              {`${item.label.trim()} `}
            </li>
          ))}
        </ol>
      </div>
    );
  }
}
